#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long countColourings(int v, int n, int k, vector<int>& color, const vector<vector<int>>& adj) {
    if (v == n) return 1;
    long long total = 0;
    for (int c = 0; c < k; c++) {
        bool ok = true;
        for (int u : adj[v]) {
            if (u < v && color[u] == c) ok = false;
        }
        if (ok) {
            color[v] = c;
            total += countColourings(v + 1, n, k, color, adj);
        }
    }
    return total;
}

int main() {
    long long n;
    long long m;
    long long k;
    cin >> n >> m >> k;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n);
    for (int i = 0; i < m; i++) {
        adj[edges[i][0] - 1].push_back((int)edges[i][1] - 1);
        adj[edges[i][1] - 1].push_back((int)edges[i][0] - 1);
    }
    vector<int> color(n, 0);
    cout << countColourings(0, (int)n, (int)k, color, adj) << "\n";

    return 0;
}

